1	package yq
2	
3	// Node mirrors the structure of gopkg.in/yaml.v3's yaml.Node.
4	// All codecs (yaml/json/xml/props/csv/...) parse into and encode from
5	// a tree of *Node. A parsed stream is a sequence of document Nodes
6	// (Kind == DocumentNode), each with exactly one child in Content[0]
7	// (which may be a null scalar for empty documents).
8	
9	type Kind int
10	
11	const (
12		DocumentNode Kind = 1 << iota
13		SequenceNode
14		MappingNode
15		ScalarNode
16		AliasNode
17	)
18	
19	type Style int
20	
21	const (
22		TaggedStyle Style = 1 << iota
23		DoubleQuotedStyle
24		SingleQuotedStyle
25		LiteralStyle
26		FoldedStyle
27		FlowStyle
28	)
29	
30	type Node struct {
31		Kind    Kind
32		Style   Style
33		Tag     string // e.g. "!!str", "!!int", "!!map", "!custom"
34		Value   string // scalar value; for AliasNode the alias name
35		Anchor  string
36		Alias   *Node   // set for AliasNode
37		Content []*Node // Mapping: key,value interleaved. Sequence: items. Document: single child.
38	
39		HeadComment string // comment lines above the node, without '#', space separated lines joined by \n
40		LineComment string // comment on the same line
41		FootComment string // comment lines following the node
42	
43		Line   int // 1-based line where node starts (best effort)
44		Column int
45	
46		// internal book-keeping (not part of yaml.v3 semantics)
47		DocSeparator bool // document was preceded by '---' in its source stream
48		DocIndex     int  // index of source document in the input stream
49	}
50	
51	// Document wraps n in a document node.
52	func Document(n *Node) *Node {
53		d := &Node{Kind: DocumentNode, Tag: "!!map"}
54		if n == nil {
55			n = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
56		}
57		d.Content = []*Node{n}
58		return d
59	}
60	
61	func Scalar(tag, value string) *Node {
62		return &Node{Kind: ScalarNode, Tag: tag, Value: value}
63	}
64	
65	func Str(value string) *Node  { return Scalar("!!str", value) }
66	func Int(value string) *Node  { return Scalar("!!int", value) }
67	func Null() *Node             { return Scalar("!!null", "") }
68	func Bool(value string) *Node { return Scalar("!!bool", value) }
69	
70	func Mapping(style Style) *Node {
71		return &Node{Kind: MappingNode, Tag: "!!map", Style: style}
72	}
73	
74	func Sequence(style Style) *Node {
75		return &Node{Kind: SequenceNode, Tag: "!!seq", Style: style}
76	}
77	
78	// Unwrap returns the innermost child for document nodes.
79	func (n *Node) Unwrap() *Node {
80		if n != nil && n.Kind == DocumentNode && len(n.Content) > 0 {
81			return n.Content[0]
82		}
83		return n
84	}
85	
86	// MapKeys returns the keys of a mapping node.
87	func (n *Node) MapKeys() []*Node {
88		n = n.Unwrap()
89		if n == nil || n.Kind != MappingNode {
90			return nil
91		}
92		keys := make([]*Node, 0, len(n.Content)/2)
93		for i := 0; i < len(n.Content); i += 2 {
94			keys = append(keys, n.Content[i])
95		}
96		return keys
97	}
98	
99	// MapValues returns the values of a mapping node.
100	func (n *Node) MapValues() []*Node {
101		n = n.Unwrap()
102		if n == nil || n.Kind != MappingNode {
103			return nil
104		}
105		vals := make([]*Node, 0, len(n.Content)/2)
106		for i := 1; i < len(n.Content); i += 2 {
107			vals = append(vals, n.Content[i])
108		}
109		return vals
110	}
111	
112	// MapGet returns the value for key, or nil.
113	func (n *Node) MapGet(key string) *Node {
114		n = n.Unwrap()
115		if n == nil || n.Kind != MappingNode {
116			return nil
117		}
118		for i := 0; i < len(n.Content); i += 2 {
119			if n.Content[i].Value == key {
120				return n.Content[i+1]
121			}
122		}
123		return nil
124	}
125	
126	// MapSet sets (or appends) a key/value pair on a mapping node.
127	func (n *Node) MapSet(key string, value *Node) {
128		if n.Kind != MappingNode {
129			return
130		}
131		for i := 0; i < len(n.Content); i += 2 {
132			if n.Content[i].Value == key {
133				n.Content[i+1] = value
134				return
135			}
136		}
137		n.Content = append(n.Content, Str(key), value)
138	}
139	
140	// DeepCopy clones the node tree (aliases are preserved as references).
141	func (n *Node) DeepCopy() *Node {
142		if n == nil {
143			return nil
144		}
145		c := *n
146		if n.Kind != AliasNode {
147			c.Content = make([]*Node, len(n.Content))
148			for i, ch := range n.Content {
149				c.Content[i] = ch.DeepCopy()
150			}
151		}
152		return &c
153	}
